import { Component, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import {
  ReactiveFormsModule,
  FormsModule,
  FormBuilder,
  FormGroup,
  Validators,
  AbstractControl,
  ValidatorFn,
  ValidationErrors,
} from '@angular/forms';
import { Router } from '@angular/router';
import { EmpresaService } from '../../../controllers/empresa.service';
import { MunicipioService } from '../../../controllers/municipio.service';
import { SectorComercialService } from '../../../controllers/sector.comercial.service';
import { TipoEmpresaService } from '../../../controllers/tipo_empresa.service';
import { ActividadEconomicaService } from '../../../controllers/actividad.economica.service';
import { Empresa } from '../../../models/empresa';
import { Municipio } from '../../../models/municipio';
import { SectorComercial } from '../../../models/sector.comercial';
import { TipoEmpresa } from '../../../models/tipo_empresa';
import { ActividadEconomica } from '../../../models/actividad.economica';
import { LocalStorageService } from '../../../services/localStorage/local-storage.service';

// Custom validator for optional min value
function optionalMinValidator(min: number): ValidatorFn {
  return (control: AbstractControl): ValidationErrors | null => {
    if (control.value === null || control.value === '' || typeof control.value !== 'number') {
      return null;
    }
    return Validators.min(min)(control);
  };
}

@Component({
  selector: 'app-usuario-empresa-form',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    FormsModule,
  ],
  templateUrl: './usuarios-empresas-form.html',
  styleUrls: ['./usuarios-empresas-form.css'],
})
export class UsuariosEmpresasForm implements OnInit {
  empresaForm!: FormGroup;
  submitted = false;
  isEditMode = false;
  loading = false;
  empresa?: Empresa;

  // Listas para selects
  municipios: Municipio[] = [];
  sectoresComerciales: SectorComercial[] = [];
  tiposEmpresa: TipoEmpresa[] = [];

  todasActividadesEconomicas: ActividadEconomica[] = [];
  actividadesEconomicasFiltradas: ActividadEconomica[] = [];

  // Opciones para tipo de persona
  tipoPersonaOptions: { value: 'fisica' | 'moral'; label: string }[] = [
    { value: 'fisica', label: 'Persona Física' },
    { value: 'moral', label: 'Persona Moral' },
  ];

  private fb = inject(FormBuilder);
  private router = inject(Router);
  private storage = inject(LocalStorageService);
  private empresaService = inject(EmpresaService);
  private municipioService = inject(MunicipioService);
  private sectorComercialService = inject(SectorComercialService);
  private tipoEmpresaService = inject(TipoEmpresaService);
  private actividadEconomicaService = inject(ActividadEconomicaService);

  async ngOnInit(): Promise<void> {
    const user = this.storage.getUser()?.user;
    if (!user) {
      this.router.navigate(['/auth/login']);
      return;
    }

    await this.loadSelectOptions();

    this.empresaForm = this.fb.group({
      tipo_persona: ['moral', Validators.required],
      rfc: [
        '',
        [
          Validators.required,
          Validators.pattern(
            /^[A-Za-z]{3,4}[0-9]{2}(0[1-9]|1[0-2])(0[1-9]|[12][0-9]|3[01])[A-Za-z0-9]{2}([A-Za-z0-9])?$/
          ),
        ],
      ],
      razon_social: ['', [Validators.required, Validators.minLength(3)]],
      nombre_comercial: [''],
      sector_comercial_id: [null, Validators.required],
      actividad_economica_id: [null, Validators.required],
      tipo_empresa_id: [null, Validators.required],
      pais_procedencia: ['México'],
      estado: ['Baja California', Validators.required],
      nombre_solicitante: [user?.name || '', [Validators.required, Validators.minLength(3)]],
      cargo_solicitante: ['', [Validators.required, Validators.minLength(2)]],
      correo_solicitante: [user?.email || '', [Validators.required, Validators.email]],
      telefono_solicitante: ['', [Validators.required, Validators.pattern(/^[0-9]{10}$/)]],
      municipio_id: [null, Validators.required],
      numero_empleados_directos: [null, [optionalMinValidator(1)]],
    });
 
   this.empresaForm.get('sector_comercial_id')?.valueChanges.subscribe(sectorId => {
    this.empresaForm.get('actividad_economica_id')?.setValue(null);
    if (sectorId) {
      this.filtrarActividadesPorSector(sectorId);
    } else {
      this.actividadesEconomicasFiltradas = [];
    }
  });
    await this.loadUserEmpresa(user.id);
  }

  private async loadSelectOptions(): Promise<void> {
    const [municipios, sectores, tipos, actividades] = await Promise.all([
      this.municipioService.get(),
      this.sectorComercialService.get(),
      this.tipoEmpresaService.get(),
      this.actividadEconomicaService.get(),
    ]);

    this.municipios = municipios.data || [];
    this.sectoresComerciales = sectores.data || [];
    this.tiposEmpresa = tipos.data || [];
    this.todasActividadesEconomicas = actividades.data || [];
  }

  private async loadUserEmpresa(userId: number | undefined): Promise<void> {
    this.loading = true;
    const empresasResponse = await this.empresaService.get({
      conditionals: { solicitante_id: userId },
      loader: false
    });
    const empresas = empresasResponse.data || [];

    if (empresas.length > 0) {
      this.isEditMode = true;
      this.empresa = empresas[0];
      this.populateForm();
    }
    this.loading = false;
  }

  private populateForm(): void {
  if (!this.empresa) return;

  // Pre-filtrar ANTES del patchValue para que no se resetee la actividad
   if (this.empresa.sector_comercial_id) {
    this.filtrarActividadesPorSector(this.empresa.sector_comercial_id);
  }

  this.empresaForm.patchValue({
    tipo_persona: this.empresa.tipo_persona,
    rfc: this.empresa.rfc,
    razon_social: this.empresa.razon_social,
    nombre_comercial: this.empresa.nombre_comercial || '',
    sector_comercial_id: this.empresa.sector_comercial_id,
    actividad_economica_id: this.empresa.actividad_economica_id,
    tipo_empresa_id: this.empresa.tipo_empresa_id,
    pais_procedencia: this.empresa.pais_procedencia || 'México',
    estado: this.empresa.estado || 'Baja California',
    nombre_solicitante: this.empresa.nombre_solicitante,
    cargo_solicitante: this.empresa.cargo_solicitante,
    correo_solicitante: this.empresa.correo_solicitante,
    telefono_solicitante: this.empresa.telefono_solicitante,
    municipio_id: this.empresa.municipio_id,
    numero_empleados_directos: this.empresa.numero_empleados_directos,
  });
}

  /**
   * Parsea el código del sector comercial y genera los prefijos para filtrar actividades.
   * Ejemplos:
   *   "11"    → ["11"]
   *   "31-33" → ["31", "32", "33"]
   *   "48-49" → ["48", "49"]
   */
  private obtenerPrefijos(codigoSector: string): string[] {
    if (!codigoSector) return [];

    // Verificar si es un rango (contiene '-')
    if (codigoSector.includes('-')) {
      const partes = codigoSector.split('-');
      const inicio = parseInt(partes[0], 10);
      const fin = parseInt(partes[1], 10);

      if (isNaN(inicio) || isNaN(fin)) return [];

      const prefijos: string[] = [];
      for (let i = inicio; i <= fin; i++) {
        prefijos.push(i.toString());
      }
      return prefijos;
    }

    // Código simple
    return [codigoSector.trim()];
  }

  /**
   * Filtra las actividades económicas según el sector seleccionado.
   * @param sectorId - ID del sector comercial seleccionado
   *  
   */
  private filtrarActividadesPorSector(sectorId: number): void {
    const sector = this.sectoresComerciales.find(s => s.id == sectorId);
    if (!sector || !sector.codigo) {
      this.actividadesEconomicasFiltradas = [];
      return;
    }
    const prefijos = this.obtenerPrefijos(sector.codigo);
    this.actividadesEconomicasFiltradas = this.todasActividadesEconomicas.filter(act => {
      if (!act.codigo) return false;
      return prefijos.some(prefijo => act.codigo.startsWith(prefijo));
    });
  }

 

  get f(): Record<string, AbstractControl> {
    if (!this.empresaForm) return {};
    return this.empresaForm.controls;
  }

  isControlInvalid(controlName: string): boolean {
    const control = this.f[controlName];
    return control ? control.invalid && (control.dirty || control.touched) : false;
  }

  hasControlError(controlName: string, errorType: string): boolean {
    const control = this.f[controlName];
    return control ? control.hasError(errorType) && (control.dirty || control.touched) : false;
  }

  async onSubmit(): Promise<void> {
    if (!this.empresaForm) {
      console.error('El formulario no está inicializado');
      return;
    }

    if (this.empresaForm.invalid) {
      this.empresaForm.markAllAsTouched();
      return;
    }

    const formData = { ...this.empresaForm.getRawValue() };
    const user = this.storage.getUser()?.user;
    if (!user) {
      console.error('Usuario no autenticado');
      return;
    }

    if (this.isEditMode && this.empresa) {
      const res = await this.empresaService.update(this.empresa.id, formData);
      if (!res.status) return;
    } else {
      const createData = {
        ...formData,
        solicitante_id: user.id,
        created_by: user.id
      };
      const res = await this.empresaService.new(createData);
      if (!res) return;
    }

    this.submitted = true;
    setTimeout(() => {
      this.router.navigate(['/main/inicio']);
    }, 2000);
  }

  onCancel(): void {
    this.router.navigate(['/main/inicio']);
  }

  get titulo(): string {
    return this.isEditMode ? 'Editar Datos de la Empresa' : 'Registrar Empresa';
  }

  get isPersonaMoral(): boolean {
    return this.empresaForm?.get('tipo_persona')?.value === 'moral';
  }

  copiarRazonSocialANombreComercial(): void {
    const razonSocial = this.empresaForm?.get('razon_social')?.value;
    if (razonSocial) {
      this.empresaForm?.get('nombre_comercial')?.setValue(razonSocial);
      this.empresaForm?.get('nombre_comercial')?.markAsTouched();
    }
  }

  get textoBoton(): string {
    return this.isEditMode ? 'Actualizar Empresa' : 'Registrar Empresa';
  }
}