import { Routes } from "@angular/router";
import { UsuariosList } from "./usuarios-list/usuarios-list";
import { UsuariosForm } from "./usuarios-form/usuarios-form";
import { UsuariosEmpresasForm } from "./usuarios-empresas-form/usuarios-empresas-form";
import { AdminGuard } from "../../guards/auth.guard";

export const usuariosRoutes: Routes = [
    {
        path: '',
        pathMatch: 'full',
        redirectTo: 'lista',
    },
    {
        path: 'lista',
        component: UsuariosList,
        title: 'Usuarios',
        canActivate: [AdminGuard],
    },
    {
        path: 'nuevo',
        title: 'Nuevo Usuario',
        component: UsuariosForm,
        canActivate: [AdminGuard],
    },
    {
        path: 'editar/:usuario_id',
        title: 'Editar Usuario',
        canActivate: [AdminGuard],
        component: UsuariosForm,
    },
    {
        path: 'editar',
        title: 'Editar Usuario',
        component: UsuariosForm,
    },
    {
        path: 'empresa',
        title: 'Datos de la Empresa',
        component: UsuariosEmpresasForm,
    },
]